#!/usr/bin/env python3
"""Final dashboard presentation patch."""
from pathlib import Path
import re
P=Path('docs/index.html'); html=P.read_text(encoding='utf-8')
# Keep existing functional patches, then replace the hierarchy/heatmap presentation with a single-column hierarchy and explicit drill-down controls.
# One top-level topic card per row avoids the awkward expansion of one card beside another.
html=re.sub(r'\.tree>ul\{[^}]*\}', '.tree>ul{padding:0;display:block}', html, count=1)
# Ensure each top-level card has comfortable vertical spacing.
if '.tree>ul>li{margin:' not in html:
    html=html.replace('</style>', '.tree>ul>li{margin:0 0 14px;background:#fff;border:1px solid var(--line);border-radius:16px;padding:14px 16px 12px;box-shadow:0 3px 12px #2c454a10;border-left:5px solid var(--mid)}.tree>ul>li:nth-child(4n+2){border-left-color:var(--sand)}.tree>ul>li:nth-child(4n+3){border-left-color:var(--coral)}.tree>ul>li:nth-child(4n+4){border-left-color:var(--pale)}</style>',1)
# Replace heatmap with true hierarchy navigation: current branch, parent/back control, and immediate children only.
start=html.index('function heat(){'); end=html.index('function tree(){',start)
heat_fn=r'''function heat(){const el=d3.select('#heatmap');el.selectAll('*').remove();const lev=heatLevel.value||'1',top=heatTop.value,sp=heatSpecies.value,limit=+heatLimit.value,counts=D.species_group_topic_level_counts?.[lev]||D.species_topic_level_counts?.[lev]||{};let selected=top==='__all__'?'':top;const allPaths=[...new Set(Object.keys(counts).map(k=>k.split('|||').slice(1).join('|||')))];const childrenOf=p=>{const out=new Set();allPaths.forEach(x=>{if(!p){out.add(x.split(' > ')[0]);}else if(x.startsWith(p+' > ')){const rest=x.slice(p.length+3);out.add(p+' > '+rest.split(' > ')[0])}});return [...out].sort((a,b)=>a.localeCompare(b))};let topics=childrenOf(selected);if(lev==='1')topics=childrenOf('').filter(x=>!x.includes(' > '));topics=topics.slice(0,limit);const species=sp==='__all__'?(D.species_display_order||Object.keys(D.species_counts)):[sp],cw=110,ch=34,left=190,bottom=250,w=Math.max(1000,left+topics.length*cw+20),h=80+species.length*ch+bottom,svg=el.append('svg').attr('width',w).attr('height',h);const nav=document.createElement('div');nav.className='heat-nav';const parent=selected.includes(' > ')?selected.split(' > ').slice(0,-1).join(' > '):'';nav.innerHTML=(selected?`<button class="heat-nav-btn" id="heatBack">← Back</button><span class="heat-path">${esc(selected)}</span>`:'<span class="heat-path">Top-level topics</span>')+`<span class="heat-help">Select a topic branch above to drill down.</span>`;el.node().prepend(nav);if(selected)document.getElementById('heatBack').onclick=()=>{heatTop.value=parent||'__all__';heat()};const max=d3.max(species.flatMap(s=>topics.map(t=>counts[`${s}|||${t}`]||0)))||1,color=d3.scaleSequential(d3.interpolateRgbBasis([palette[2],palette[1],palette[0],palette[5]])).domain([1,max]);species.forEach((s,i)=>topics.forEach((t,j)=>{const n=counts[`${s}|||${t}`]||0;svg.append('rect').attr('x',left+j*cw).attr('y',40+i*ch).attr('width',cw).attr('height',ch).attr('fill',n===0?'#f8f9f8':color(n)).attr('class','heat-cell').on('click',()=>setFilter({species:s,topic:t})).on('mousemove',e=>showTip(e,`<b>${esc(s==='Unspecified species'?'Unspecified salmon':s)}</b><br>${esc(t)}<br>${fmt(n)} unique articles`)).on('mouseleave',hideTip)}));svg.selectAll('.slabel').data(species).join('text').attr('x',left-8).attr('y',(s,i)=>40+i*ch+22).attr('text-anchor','end').attr('class','axis').text(s=>s==='Unspecified species'?'Unspecified salmon':s);svg.selectAll('.tlabel').data(topics).join('text').attr('transform',(t,i)=>`translate(${left+i*cw+cw/2},${40+species.length*ch+22}) rotate(-55)`).attr('text-anchor','end').attr('class','axis').text(t=>t.length>38?t.slice(0,36)+'…':t)}'''
html=html[:start]+heat_fn+'\n'+html[end:]
# Heatmap navigation styling.
heat_css='.heat-nav{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:0 0 10px;padding:8px 12px;background:#f5f8f7;border:1px solid var(--line);border-radius:10px}.heat-nav-btn{border:1px solid var(--line);border-radius:999px;background:#fff;padding:5px 12px;cursor:pointer}.heat-path{font-weight:700}.heat-help{font-size:12px;color:var(--mid);margin-left:auto}'
if '.heat-nav{' not in html: html=html.replace('</style>',heat_css+'</style>',1)
P.write_text(html,encoding='utf-8')
print('Applied single-column topic hierarchy and explicit heatmap drill-down UX')